<?php require __DIR__.'/../bootstrap/app.php';if(user())go('dashboard.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$nm=trim((string)($_POST['name']??''));$em=trim((string)($_POST['email']??''));$pw=(string)($_POST['password']??'');if(!throttle('register',5,3600))$err='Too many attempts. Please try later.';elseif(mb_strlen($nm)<2||mb_strlen($nm)>120||!filter_var($em,FILTER_VALIDATE_EMAIL)||strlen($pw)<10)$err='Enter a valid name, a valid email and a password of 10+ characters.';else try{Auth::register($nm,$em,$pw);notice('Account created. Please sign in.');go('login.php');}catch(Throwable $e){$err='Registration failed. Check fields and ensure email is not already used.';}}$title='Register';require __DIR__.'/../app/Views/header.php';?><section class="section"><div class="container" style="max-width:600px"><form class="formbox" method="post"><h1>Create customer account</h1><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><?=csrf_field()?><label class="form-label">Full name</label><input class="form-control mb-3" name="name" required><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Password (10+ characters)</label><input class="form-control mb-3" type="password" name="password" minlength="10" required><button class="btn gold">Register</button></form></div></section><?php require __DIR__.'/../app/Views/footer.php';?>